import math


def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("coordinates must be numbers")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError("coordinates must be finite")
    return value


def _triple(value, field):
    if not isinstance(value, (list, tuple)):
        raise TypeError(f"{field} must be a sequence")
    if len(value) != 3:
        raise ValueError(f"{field} must contain three values")
    return tuple(_number(item) for item in value)


def export_model(objects, *, scale=1.0, apply_offsets=False):
    if not isinstance(objects, list):
        raise TypeError("objects must be a list")
    scale = _number(scale)
    if scale <= 0:
        raise ValueError("scale must be positive")
    if not isinstance(apply_offsets, bool):
        raise TypeError("apply_offsets must be a boolean")

    prepared = []
    for obj in objects:
        if not isinstance(obj, dict):
            raise TypeError("each object must be a dictionary")
        name = obj.get("name")
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        if not name or "\n" in name or "\r" in name:
            raise ValueError("invalid object name")
        vertices = obj.get("vertices")
        if not isinstance(vertices, list):
            raise TypeError("vertices must be a list")
        offset = _triple(obj.get("offset", (0, 0, 0)), "offset")
        prepared.append((name, [_triple(v, "vertex") for v in vertices], offset))

    output = ["MODEL 1\n"]
    for name, vertices, offset in prepared:
        output.append(f"OBJECT {name} {len(vertices)}\n")
        ox, oy, oz = offset if apply_offsets else (0.0, 0.0, 0.0)
        for x, y, z in vertices:
            output.append(f"V {(x + ox) * scale:.6g} {(y + oy) * scale:.6g} {z + oz:.6g}\n")
    return "".join(output)

